'use client'

import AutoSizeImage from '@/components/ui/auto-size-image/AutoSizeImage'
import dummyImage from '@/assets/image.jpg'
import Link from 'next/link'
import Button from '@/components/ui/button/Button'
import { useState } from 'react'
import Input from '@/components/ui/input/Input'
import { Draggable, DropResult } from '@hello-pangea/dnd'
import { DndContext } from '@/contexts/DndContext'
import clsx from 'clsx'
import { TChapter, TCourse } from '@/types/course'

const reorder = (
  list: TChapter[],
  startIndex: number,
  endIndex: number,
): TChapter[] => {
  const result = Array.from(list)
  const [removed] = result.splice(startIndex, 1)
  result.splice(endIndex, 0, removed)
  return result
}

interface TProps {
  course: TCourse
}

const LecturesArea = ({ course }: TProps) => {
  console.log(course.chapters)
  const [chapters, setChapters] = useState<TChapter[]>(course.chapters)
  const [editChapterId, setEditChapterId] = useState<string | null>(null)
  const [editChapterTitle, setEditChapterTitle] = useState<string>('')

  const [editLectureOrQuizId, setEditLectureOrQuizId] = useState<string | null>(
    null,
  )
  const [editLectureOrQuizTitle, setEditLectureOrQuizTitle] =
    useState<string>('')

  const [isClickedChapter, setIsClickedChapter] = useState<string | null>(null)

  //챕터추가
  const handleAddChapter = () => {
    setChapters((prevState) => {
      return [
        ...prevState,
        {
          chapterId: undefined,
          title: `CHAPTER ${prevState.length + 1}`,
          lectures: [],
          quizs: [],
        },
      ]
    })
  }

  //챕터삭제
  const handleDeleteChapter = (id: string) => {
    setChapters((prevState) =>
      prevState.filter((chapter) => chapter.chapterId !== id),
    )
  }

  //수정
  const handleEditChapter = (id?: string, title?: string) => {
    if (id && title) {
      setEditChapterId(id)
      setEditChapterTitle(title)
    } else {
      setEditChapterId(null)
      setEditChapterTitle('')
    }
  }

  //챕터 제목 내용 변경
  const handleChangeChapterTitle = (e: React.ChangeEvent<HTMLInputElement>) => {
    setEditChapterTitle(e.target.value)
  }

  //챕터 변경 후 제목 저장
  const handleSaveChapter = (id: string, newTitle: string) => {
    const updatedChapters = chapters.map((chapter) => {
      return chapter.chapterId === id
        ? { ...chapter, title: newTitle }
        : chapter
    })

    setChapters(updatedChapters)
    handleEditChapter()
  }

  //드래그 클릭
  const handleClickedChapter = (id?: string) => {
    if (id) {
      setIsClickedChapter(id)
    } else {
      setIsClickedChapter(null)
    }
  }

  //강의 또는 퀴즈 추가
  const handleAddLectureOrQuiz = (
    chapterId: string,
    type: 'lecture' | 'quiz',
  ) => {
    setChapters((prevState) =>
      prevState.map((chapter) => {
        if (chapter.chaterId === chapterId && chapter.lectures) {
          return {
            ...chapter,
            lectures: [
              ...chapter.lectures,
              {
                id: chapter.lectures.length + 1,
                type,
                title: type === 'lecture' ? '강의 추가' : '퀴즈 추가',
              },
            ],
          }
        }
        return chapter
      }),
    )
  }

  const handleDeleteLectureOrQuiz = (
    event: React.MouseEvent<HTMLButtonElement>,
    chapterId: string,
    lectureId: string,
  ) => {
    event.preventDefault()

    setChapters((prevState) =>
      prevState.map((chapter) => {
        if (chapter.chapterId === chapterId && chapter.lectures) {
          return {
            ...chapter,
            lectures: chapter.lectures.filter(
              (lecture) => lecture.lectureId !== lectureId,
            ),
          }
        }
        return chapter
      }),
    )
  }

  //수정
  const handleEditLectureOrQuiz = (
    event: React.MouseEvent<HTMLButtonElement>,
    chapterId: string | null,
    lectureId: string | null,
    title?: string,
  ) => {
    event.preventDefault()

    if (chapterId && lectureId && title) {
      setEditChapterId(chapterId)
      setEditLectureOrQuizId(lectureId)
      setEditLectureOrQuizTitle(title)
    } else {
      setEditChapterId(null)
      setEditLectureOrQuizId(null)
      setEditLectureOrQuizTitle('')
    }
  }

  //강의 또는 퀴즈 제목 내용 변경
  const handleChangeLectureOrQuizTitle = (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => {
    setEditLectureOrQuizTitle(e.target.value)
  }

  //강의 또는 퀴즈 변경 내용저장

  const handleSaveLectureOrQuiz = (
    event: React.MouseEvent<HTMLButtonElement>,
    chapterId: string,
    lectureId: string,
    newTitle: string,
  ) => {
    event.preventDefault()
    setChapters((prevState) =>
      prevState.map((chapter) => {
        if (chapter.chapterId === chapterId && chapter.lectures) {
          return {
            ...chapter,
            lectures: chapter.lectures.map((lecture) =>
              lecture.lectureId === lectureId
                ? { ...lecture, title: newTitle }
                : lecture,
            ),
          }
        }
        return chapter
      }),
    )

    setEditChapterId(null)
    setEditLectureOrQuizId(null)
  }

  const onDragEnd = (result: DropResult) => {
    if (!result.destination) return

    const updatedChapters = reorder(
      chapters,
      result.source.index,
      result.destination.index,
    )

    setChapters(updatedChapters)
  }

  return (
    <main className="flex h-screen">
      <aside className="min-w-[32rem] border-r border-gray-100">
        <div className="flex h-[20rem] flex-col bg-green-600 p-10">
          <div className="flex-1">
            <h2 className="text-3xl font-bold text-white">이론 교육 제목</h2>
          </div>
          <div className="flex items-center gap-6">
            <span>
              <AutoSizeImage
                src={dummyImage}
                alt="profile"
                className="h-[3.2rem] w-[3.2rem]"
              />
            </span>
            <div className="text-white">
              <span>유호빈</span>
              <span className="before-pipe before:mx-2 before:h-[10px]">
                DGIST
              </span>
            </div>
          </div>
        </div>
        <div className="p-[2.4rem]">
          <Button className="mb-5 text-2xl font-bold">강의</Button>

          <ul className="flex flex-col gap-y-5 text-xl">
            {chapters.map((chapter) => (
              <li key={chapter.chapterId} className="flex flex-col gap-y-4">
                <span> {chapter.title}</span>
                {chapter.lectures?.map((lecture) => (
                  <Link
                    key={lecture.lectureId}
                    className="text-gray-500 before:mr-2 before:font-bold before:content-['·'] hover:text-green-600"
                    href={`/lectures/${lecture.lectureId}/edit`}
                  >
                    {lecture.title}
                  </Link>
                ))}
              </li>
            ))}
          </ul>
        </div>
      </aside>

      <section className="mx-auto min-w-[84rem] px-[4rem] pb-[12rem] pt-[7.4rem]">
        <header>
          <h1 className="text-4xl font-bold">강의</h1>
        </header>

        <div className="relative mt-[5rem] flex flex-col gap-12">
          <div className="flex justify-end">
            <Button
              className="h-[3.2rem] w-[9rem] rounded-md bg-gray-200 "
              onClick={handleAddChapter}
            >
              챕터추가
            </Button>
          </div>

          <DndContext onDragEnd={onDragEnd}>
            {chapters.map((chapter, index) => {
              const isChapterIdEqual =
                editChapterId === chapter.chapterId && !editLectureOrQuizId

              return (
                <Draggable
                  key={chapter.chapterId}
                  draggableId={chapter.chapterId}
                  index={index}
                >
                  {(provided, snapshot) => (
                    <div
                      ref={provided.innerRef}
                      {...provided.draggableProps}
                      {...provided.dragHandleProps}
                      className="mb-6"
                    >
                      <div
                        className={clsx(
                          'mb-6 flex h-[7.1rem] items-center justify-between rounded-md border border-gray-200 px-10 transition-none hover:border-green-600',
                          snapshot.isDragging && 'border-green-600',
                        )}
                      >
                        {isChapterIdEqual ? (
                          <>
                            <Input
                              id="courseName"
                              type="courseName"
                              name="courseName"
                              className="h-16 w-full bg-gray-200"
                              value={editChapterTitle}
                              onChange={handleChangeChapterTitle}
                            />
                            <div className="flex">
                              <Button
                                onClick={() =>
                                  handleSaveChapter(
                                    chapter.chapterId,
                                    editChapterTitle,
                                  )
                                }
                              >
                                저장 후 이동
                              </Button>
                              <Button
                                className="before-pipe before:mx-2 before:h-[10px]"
                                onClick={() =>
                                  handleSaveChapter(
                                    chapter.chapterId,
                                    editChapterTitle,
                                  )
                                }
                              >
                                저장
                              </Button>
                              <Button
                                className="before-pipe before:mx-2 before:h-[10px]"
                                onClick={() => handleEditChapter()}
                              >
                                취소
                              </Button>
                            </div>
                          </>
                        ) : (
                          <>
                            <p className="text-2xl">{chapter.title}</p>
                            <div className="flex">
                              <Button
                                onClick={() =>
                                  handleEditChapter(
                                    chapter.chapterId,
                                    chapter.title,
                                  )
                                }
                              >
                                수정
                              </Button>
                              <Button
                                className="before-pipe before:mx-2 before:h-[10px]"
                                onClick={() =>
                                  handleDeleteChapter(chapter.chapterId)
                                }
                              >
                                삭제
                              </Button>
                              <Button className="before:mx-2">드래그</Button>
                            </div>
                          </>
                        )}
                      </div>

                      <div>
                        {chapter.lectures &&
                          chapter.lectures.map((lecture) => {
                            const isLectureIdEqual =
                              editChapterId === chapter.chapterId &&
                              editLectureOrQuizId === lecture.lectureId

                            return (
                              <Link
                                href="/"
                                className="mb-3 flex h-[11rem] items-center justify-between rounded-md border border-gray-200 px-10 hover:border-green-600"
                                key={lecture.lectureId}
                              >
                                {isLectureIdEqual ? (
                                  <>
                                    <Input
                                      id="courseName"
                                      type="courseName"
                                      name="courseName"
                                      className="h-16 w-full bg-gray-200"
                                      value={editLectureOrQuizTitle}
                                      onChange={handleChangeLectureOrQuizTitle}
                                      onClick={(e) => e.preventDefault()}
                                    />
                                    <div className="flex">
                                      <Button
                                        onClick={(e) =>
                                          handleSaveLectureOrQuiz(
                                            e,
                                            chapter.chapterId,
                                            lecture.lectureId,
                                            editLectureOrQuizTitle,
                                          )
                                        }
                                      >
                                        저장 후 이동
                                      </Button>
                                      <Button
                                        className="before-pipe before:mx-2 before:h-[10px]"
                                        onClick={(e) =>
                                          handleSaveLectureOrQuiz(
                                            e,
                                            chapter.chapterId,
                                            lecture.lectureId,
                                            editLectureOrQuizTitle,
                                          )
                                        }
                                      >
                                        저장
                                      </Button>
                                      <Button
                                        className="before-pipe before:mx-2 before:h-[10px]"
                                        onClick={(e) =>
                                          handleEditLectureOrQuiz(e, null, null)
                                        }
                                      >
                                        취소
                                      </Button>
                                    </div>
                                  </>
                                ) : (
                                  <>
                                    <p className="text-xl">{lecture.title}</p>
                                    <div className="flex">
                                      <Button
                                        onClick={(e) =>
                                          handleEditLectureOrQuiz(
                                            e,
                                            chapter.chapterId,
                                            lecture.lectureId,
                                            lecture.title,
                                          )
                                        }
                                      >
                                        수정
                                      </Button>
                                      <button
                                        className="before-pipe before:mx-2 before:h-[10px]"
                                        onClick={(e) =>
                                          handleDeleteLectureOrQuiz(
                                            e,
                                            chapter.chapterId,
                                            lecture.lectureId,
                                          )
                                        }
                                      >
                                        삭제
                                      </button>
                                    </div>
                                  </>
                                )}
                              </Link>
                            )
                          })}
                      </div>
                      <div className="flex gap-4">
                        <Button
                          className="h-20 w-full rounded-md border"
                          onClick={() =>
                            handleAddLectureOrQuiz(chapter.chapterId, 'lecture')
                          }
                        >
                          강의추가
                        </Button>
                        <Button
                          className="h-20 w-full rounded-md border"
                          onClick={() =>
                            handleAddLectureOrQuiz(chapter.chapterId, 'quiz')
                          }
                        >
                          퀴즈추가
                        </Button>
                      </div>
                    </div>
                  )}
                </Draggable>
              )
            })}
          </DndContext>
        </div>
      </section>
    </main>
  )
}

export default LecturesArea

